const msg = String($json.message || '').trim();
const lower = msg.toLowerCase();
const stop = new Set([
  'quiero','quisiera','gustaria','gustaría','busco','necesito',
  'un','una','unos','unas','el','la','los','las','de','del','para','por',
  'me','mi','con','y','o','que','como','hola','buenas','buen','dia','tarde','noche',
  'comprar','compra','producto','productos','favor','porfavor','algo',
  'tiene','tienen','hay','confirmo','dale','si','sí','ok','okay','claro'
]);
const tokens = lower
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9\s]/g, ' ')
  .split(/\s+/)
  .filter(Boolean);
const keep = (t) =>
  !stop.has(t) &&
  (t.length >= 3 || /^\d+$/.test(t) || /^[a-z]*\d+[a-z\d]*$/i.test(t));
let keywords = tokens.filter(keep);
const brand = lower.match(
  /lenovo|asus|acer|dell|hp|msi|apple|samsung|logitech|razer|corsair|kingston|laptop|teclado|mouse|monitor|ram|ssd|audifonos|audifonos/
);
if (brand) {
  const b = brand[0].normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  if (!keywords.includes(b)) keywords.unshift(b);
}
keywords = [...new Set(keywords)];
const query = keywords.slice(0, 5).join(' ');
return [{ json: { ...$json, search_query: query, should_search: query.length > 0 } }];

const input = $('Normalize Input').first().json;
const extract = $('Extract Search Query').first().json;
let search = {};
try { search = $('HTTP Search').first().json || {}; } catch (e) {
  try { search = $('Empty Search Results').first().json || {}; } catch (e2) { search = {}; }
}

function mapProduct(p) {
  if (!p || typeof p !== 'object') return null;
  const id = Number(p.product_id ?? p.productId ?? p.ProductId ?? 0);
  if (!id) return null;
  return {
    product_id: id,
    name: String(p.name ?? p.Name ?? ''),
    description: p.description ?? p.Description ?? null,
    price: Number(p.price ?? p.Price ?? 0),
    category_name: String(p.category_name ?? p.categoryName ?? p.CategoryName ?? ''),
    status_name: String(p.status_name ?? p.statusName ?? p.StatusName ?? ''),
    current_stock: Number(p.current_stock ?? p.currentStock ?? p.CurrentStock ?? 0),
    image_url: p.image_url ?? p.imageUrl ?? p.ImageUrl ?? null
  };
}

const raw = search.products || (search.data && search.data.products) || [];
let products = Array.isArray(raw) ? raw.map(mapProduct).filter(Boolean) : [];
const q = String(extract.search_query || '');
const _tokens = q.trim().toLowerCase().split(/\s+/).filter(t => t.length >= 1);
if (_tokens.length) {
  const _strict = products.filter(p => {
    const name = String(p.name || '').toLowerCase();
    return _tokens.every(t => name.includes(t));
  });
  if (_strict.length) products = _strict;
}
const shouldSearch = !!extract.should_search;
let message = String(input.message || '');
const lowerMsg = message.toLowerCase();
const sessionId = String(input.session_id || 'anon');

const is_confirm = /\b(si|sí|dale|ok|okay|confirmo|claro|yes)\b/i.test(lowerMsg.trim())
  && lowerMsg.trim().split(/\s+/).length <= 4;
const is_escalate = /asesor|humano|persona|soporte humano|reclamo|garantia|garantía/i.test(lowerMsg);
const has_invoice = /FAC-\d+/i.test(message) || /\bfactura\b/i.test(lowerMsg);

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
const pending = staticData.sessions[sessionId]?.pending || null;

if (products.length > 0 && shouldSearch) {
  message += '\n\n[CONTEXTO SISTEMA - búsqueda previa OK para "' + q + '"]\n'
    + JSON.stringify({ found: true, products })
    + '\nSi el contexto trae products, NO llames search_product de nuevo. '
    + 'Incluye products en el JSON final. '
    + 'NUNCA digas que hubo un problema al buscar.';
} else if (shouldSearch) {
  message += '\n\n[CONTEXTO SISTEMA - búsqueda previa de "' + q
    + '" sin resultados]. Puedes reintentar search_product con otra keyword corta.';
}

if (pending && is_confirm) {
  message += '\n\n[CONFIRMACION PENDIENTE]\n'
    + 'product_id=' + pending.product_id
    + ', quantity=' + (pending.quantity || 1)
    + ', name=' + JSON.stringify(pending.name || '')
    + '\nEl usuario CONFIRMÓ. Llama create_sale YA con esos ids, luego notify_advisor(shipping_verification).';
} else if (pending && !is_confirm && !is_escalate && !has_invoice) {
  message += '\n\n[PRODUCTO PENDIENTE]\n'
    + 'Hay un producto pendiente de confirmación: '
    + JSON.stringify(pending.name || '')
    + ' (id=' + pending.product_id + ', qty=' + (pending.quantity || 1) + '). '
    + 'Recuérdale al cliente o espera confirmación (sí/confirmo).';
}

return [{
  json: {
    session_id: sessionId,
    message,
    search_query: q,
    should_search: shouldSearch,
    prefetched_products: products,
    pending,
    is_confirm,
    is_escalate,
    has_invoice
  }
}];

