const agent = $json;
const prep = $('Prepare Agent Context').first().json;
const sessionId = String(prep.session_id || $('Normalize Input').first().json.session_id || 'anon');

function mapProduct(p) {
  if (!p || typeof p !== 'object') return null;
  const id = Number(p.product_id ?? p.productId ?? p.ProductId ?? 0);
  if (!id) return null;
  return {
    product_id: id,
    name: String(p.name ?? p.Name ?? ''),
    description: p.description ?? p.Description ?? null,
    price: Number(p.price ?? p.Price ?? 0),
    category_name: String(p.category_name ?? p.categoryName ?? p.CategoryName ?? ''),
    status_name: String(p.status_name ?? p.statusName ?? p.StatusName ?? ''),
    current_stock: Number(p.current_stock ?? p.currentStock ?? p.CurrentStock ?? 0),
    image_url: p.image_url ?? p.imageUrl ?? p.ImageUrl ?? null
  };
}

function safeParse(raw) {
  if (raw == null) return null;
  if (typeof raw === 'object') return raw;
  const s = String(raw).trim();
  if (!s) return null;
  try { return JSON.parse(s); } catch (e) {}
  try {
    const m = s.match(/\{[\s\S]*\}/);
    if (m) return JSON.parse(m[0]);
  } catch (e2) {}
  return null;
}

function toolName(step) {
  const a = step?.action || step || {};
  return String(
    a.tool || a.toolName || a.name || a.tool_name
    || step?.tool || step?.name || ''
  ).toLowerCase();
}

function toolObs(step) {
  if (step == null) return null;
  if (typeof step.observation !== 'undefined') return step.observation;
  if (typeof step.output !== 'undefined') return step.output;
  if (typeof step.result !== 'undefined') return step.result;
  return null;
}

function collectSteps(src) {
  const out = [];
  const candidates = [
    src?.intermediateSteps,
    src?.intermediate_steps,
    src?.steps,
    src?.data?.intermediateSteps
  ];
  for (const c of candidates) {
    if (Array.isArray(c)) out.push(...c);
  }
  return out;
}

const rawOut = String(agent.output ?? agent.text ?? agent.response ?? agent.error?.message ?? '');
let parsed = safeParse(rawOut);
if (!parsed || typeof parsed !== 'object') {
  parsed = {
    response: (rawOut && !/max iterations/i.test(rawOut))
      ? rawOut
      : 'Estoy procesando tu solicitud. ¿Puedes repetir qué producto buscas?',
    state: 'IN_PROGRESS',
    invoice_number: null,
    sale_origin: null,
    products: []
  };
}

let products = [];
if (Array.isArray(parsed.products)) {
  products = parsed.products.map(mapProduct).filter(Boolean);
}

if (products.length === 0) {
  const pref = prep.prefetched_products;
  if (Array.isArray(pref) && pref.length) {
    products = pref.map(mapProduct).filter(Boolean);
  }
}

const steps = collectSteps(agent);
for (const step of steps) {
  const name = toolName(step);
  if (!name.includes('search_product') && !name.includes('search')) continue;
  if (name.includes('check_stock')) continue;
  const obs = safeParse(toolObs(step));
  if (!obs) continue;
  const list = obs.products || (obs.data && obs.data.products) || [];
  if (Array.isArray(list) && list.length) {
    const mapped = list.map(mapProduct).filter(Boolean);
    if (mapped.length) {
      const byId = new Map(products.map(p => [p.product_id, p]));
      for (const m of mapped) byId.set(m.product_id, m);
      products = [...byId.values()];
    }
  }
}

try {
  const qFilter = String(prep.search_query || '').trim();
  const _tokens = qFilter.toLowerCase().split(/\s+/).filter(t => t.length >= 1);
  if (_tokens.length && products.length) {
    const _strict = products.filter(p => {
      const name = String(p.name || '').toLowerCase();
      return _tokens.every(t => name.includes(t));
    });
    if (_strict.length) products = _strict;
  }
} catch (e) {}

let state = String(parsed.state || 'IN_PROGRESS').toUpperCase();
const allowed = new Set(['IN_PROGRESS', 'SALE_COMPLETED', 'WAITING_HUMAN_AGENT', 'ERROR']);
if (!allowed.has(state)) state = 'IN_PROGRESS';

let invoice = parsed.invoice_number ?? parsed.invoiceNumber ?? null;
if (invoice != null) invoice = String(invoice);
let saleOrigin = parsed.sale_origin ?? parsed.saleOrigin ?? null;
let saleId = parsed.sale_id ?? parsed.saleId ?? null;
if (saleId != null && saleId !== '') saleId = Number(saleId);
else saleId = null;

let _need_notify = false;
let _notify_body = null;
let response = String(parsed.response || '').trim();

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};

function clearPending() {
  if (staticData.sessions[sessionId]) {
    delete staticData.sessions[sessionId].pending;
    if (!Object.keys(staticData.sessions[sessionId]).length) {
      delete staticData.sessions[sessionId];
    }
  }
}

function clearSession() {
  delete staticData.sessions[sessionId];
}

for (const step of steps) {
  const name = toolName(step);
  if (!name.includes('create_sale') && !name.includes('sale')) continue;
  if (name.includes('notify')) continue;
  const obs = safeParse(toolObs(step));
  if (!obs) continue;
  const ok = obs.success === true
    || obs.ok === true
    || !!(obs.invoiceNumber || obs.invoice_number || obs.saleId || obs.sale_id);
  const fail = obs.success === false || obs.ok === false || obs.error || obs.message === 'error';
  if (ok && !fail) {
    state = 'SALE_COMPLETED';
    invoice = String(obs.invoiceNumber || obs.invoice_number || invoice || '');
    saleOrigin = 'CHATBOT';
    const sid = obs.saleId ?? obs.sale_id ?? saleId;
    saleId = sid != null && sid !== '' ? Number(sid) : null;
    _need_notify = true;
    _notify_body = {
      sessionId,
      notificationType: 'shipping_verification',
      details: 'Venta completada vía chatbot. Factura: ' + (invoice || 'N/A'),
      saleId: saleId
    };
    clearPending();
  } else if (fail || obs.success === false) {
    state = 'IN_PROGRESS';
    _need_notify = true;
    _notify_body = {
      sessionId,
      notificationType: 'sale_problem',
      details: String(obs.message || obs.error || obs.details || 'Error al crear venta en chatbot'),
      saleId: null
    };
    clearPending();
    if (!response || /procesando/i.test(response)) {
      response = 'No pude completar la compra. Un asesor revisará el caso. ¿Quieres intentar de nuevo o hablar con un humano?';
    }
  }
}

for (const step of steps) {
  const name = toolName(step);
  if (!name.includes('escalate')) continue;
  const obs = safeParse(toolObs(step));
  if (!obs) continue;
  const requiresLogin = obs.requires_login === true
    || obs.requiresLogin === true
    || /login|iniciar sesi[oó]n|autentic/i.test(String(obs.message || obs.error || ''));
  const escOk = obs.success === true || obs.ok === true || obs.escalated === true;
  if (requiresLogin && !escOk) {
    state = 'IN_PROGRESS';
    response = 'Para conectarte con un asesor humano necesitas iniciar sesión. Inicia sesión y vuelve a pedirlo.';
    clearPending();
  } else if (escOk) {
    state = 'WAITING_HUMAN_AGENT';
    clearSession();
    if (!response || /procesando/i.test(response)) {
      response = 'Te conecté con un asesor humano. En un momento te atenderán aquí mismo.';
    }
  } else if (obs.success === false) {
    state = 'IN_PROGRESS';
    if (requiresLogin) {
      response = 'Para conectarte con un asesor humano necesitas iniciar sesión. Inicia sesión y vuelve a pedirlo.';
    }
    clearPending();
  }
}

const isConfirm = !!prep.is_confirm;
if (state === 'IN_PROGRESS' && products.length === 1 && !isConfirm) {
  const p = products[0];
  if (!staticData.sessions[sessionId]) staticData.sessions[sessionId] = {};
  staticData.sessions[sessionId].pending = {
    product_id: p.product_id,
    quantity: 1,
    name: p.name
  };
}

const fallbackLike = !response
  || /procesando tu solicitud|repetir qu[eé] producto|max iterations|sin respuesta/i.test(response);

if (/problema al buscar|error al buscar|no devolvi[oó]|max iterations/i.test(response) && products.length > 0) {
  response = 'Encontré estas opciones para ti. Elige en las tarjetas de abajo o dime cuál te interesa.';
}

if (products.length > 0 && fallbackLike) {
  const q = String(prep.search_query || '').trim();
  response = q
    ? (products.length === 1
        ? ('Encontré 1 opción para "' + q + '". Elige en las tarjetas o dime cuál te interesa.')
        : ('Encontré ' + products.length + ' opción(es) para "' + q + '". Elige en las tarjetas o dime cuál te interesa.'))
    : 'Encontré estas opciones para ti. Elige en las tarjetas de abajo o dime cuál te interesa.';
}

response = response.replace(/!\[[^\]]*\]\([^)]*\)/gi, '');
response = response.replace(/https?:\/\/\S+\.(?:png|jpe?g|gif|webp|svg)(\?\S*)?/gi, '');
response = response.replace(/https?:\/\/\S*cloudinary\S*/gi, '');
response = response.replace(/https?:\/\/\S*\/image\S*/gi, '');
response = response.trim();

const looksLikeCatalog = /\*\*Precio\*\*|Stock disponible|\d+\.\s*\*\*/i.test(response);
if (products.length > 0 && (looksLikeCatalog || response.length > 420)) {
  response = 'Encontré estas opciones para ti. Elige en las tarjetas de abajo o dime cuál te interesa.';
}

if (!response) {
  response = products.length > 0
    ? 'Encontré estas opciones para ti. Elige en las tarjetas de abajo o dime cuál te interesa.'
    : 'Estoy aquí para ayudarte. ¿Qué producto buscas?';
}

if (state === 'SALE_COMPLETED' && !saleOrigin) saleOrigin = 'CHATBOT';

// Guaranteed HTTP notify if Agent skipped notify_advisor after sale success/fail
let agentNotified = false;
for (const step of steps) {
  if (!toolName(step).includes('notify')) continue;
  const obs = safeParse(toolObs(step));
  if (obs && (obs.success === true || obs.ok === true || obs.notified === true)) {
    agentNotified = true;
  } else if (obs == null && toolObs(step) != null) {
    // Non-JSON observation but tool ran — treat as attempted notify
    agentNotified = true;
  }
}

let saleSucceeded = false;
let saleFailed = false;
for (const step of steps) {
  const name = toolName(step);
  if (name.includes('notify')) continue;
  if (!name.includes('create_sale') && !name.includes('sale')) continue;
  const obs = safeParse(toolObs(step));
  if (!obs) continue;
  const ok = obs.success === true
    || obs.ok === true
    || !!(obs.invoiceNumber || obs.invoice_number || obs.saleId || obs.sale_id);
  if (ok && obs.success !== false) saleSucceeded = true;
  if (obs.success === false || obs.ok === false) saleFailed = true;
}

if (agentNotified) {
  _need_notify = false;
  _notify_body = null;
} else if (saleSucceeded || state === 'SALE_COMPLETED') {
  _need_notify = true;
  _notify_body = {
    sessionId,
    notificationType: 'shipping_verification',
    details: 'Venta completada vía chatbot. Factura: ' + (invoice || 'N/A'),
    saleId: saleId
  };
} else if (saleFailed) {
  _need_notify = true;
  _notify_body = {
    sessionId,
    notificationType: 'sale_problem',
    details: 'Error al crear venta en chatbot',
    saleId: null
  };
}

return [{
  json: {
    response,
    state,
    invoice_number: invoice,
    sale_origin: saleOrigin,
    products,
    _need_notify: !!_need_notify,
    _notify_body: _need_notify ? _notify_body : null
  }
}];

let j = {};
try { j = $('Enrich From Tools').first().json || {}; } catch (e) { j = $json || {}; }
return [{
  json: {
    response: j.response,
    state: j.state,
    invoice_number: j.invoice_number ?? null,
    sale_origin: j.sale_origin ?? null,
    products: Array.isArray(j.products) ? j.products : []
  }
}];
